(function (root) {
  'use strict';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const date = time => Number.isFinite(time) ? new Date(time).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '尚无记录';
  const fieldNames = { meaning: '中文释义', english: '英文释义', example: '例句', synonyms: '近义词', derivatives: '派生词', source: '来源 / 排版' };
  function wordDetails(word, flags = [], expanded = true) {
    const relevant = flags.filter(f => String(f.wordId) === String(word.id));
    const defs = word.definitions?.length ? word.definitions : [{ pos: word.pos, meaning: word.meaning }];
    return `<section class="entry-details"><div class="entry-heading"><h3>完整词条 <span class="muted">${defs.length} 个考法</span></h3><button class="text-link" data-action="toggle-definitions">${expanded ? '收起全部释义' : '展开全部释义'}</button></div>${defs.map((d, i) => `<details class="definition" ${expanded ? 'open' : ''}><summary><span class="sense-index">考法 ${i + 1}</span><span><em>${esc(d.pos || word.pos)}</em> ${esc(d.meaning)}</span>${relevant.some(f => f.senseIndex === i && ['meaning', 'english'].includes(f.field)) ? '<span class="quality-badge">释义待核验</span>' : ''}</summary><div class="definition-body">${['meaning', 'english', 'example', 'synonyms', 'derivatives'].map(field => `<div class="definition-field"><h4>${fieldNames[field]}${relevant.some(f => f.senseIndex === i && f.field === field) ? ' <span class="quality-badge">待核验</span>' : ''}</h4><p ${field === 'english' ? 'lang="en"' : ''}>${d[field] ? esc(d[field]) : '<span class="muted">原词表未提供</span>'}</p>${relevant.filter(f => f.senseIndex === i && f.field === field).map(f => `<p class="quality-note">${esc(f.message)}</p>`).join('')}</div>`).join('')}${relevant.filter(f => (f.senseIndex === i || f.senseIndex == null) && f.field === 'source').map(f => `<p class="quality-note">来源记录：${esc(f.message)}</p>`).join('')}<p class="relation-note">近义词仅对应此考法的关联用法，不表示在所有语境中可以互换。</p></div></details>`).join('')}<p class="entry-source">《GRE800词 》· PDF 第 ${esc(word.page)} 页 · List ${esc(word.group)} · #${String(word.id).padStart(3, '0')}。保留原文，疑点另行标记。</p></section>`;
  }
  function analytics(state, words, P) {
    const now = Date.now(), stats = P.getStats(state.records, words, now, state.settings);
    const trend = P.dailyTrend(state.daily || {}, 14, now);
    const max = Math.max(1, ...trend.map(d => d.attempts));
    const chart = (key, label, unit) => `<figure class="trend-panel"><figcaption>${label}</figcaption><div class="trend-chart">${trend.map(d => { const value = key === 'attempts' ? d.attempts : d.accuracy; return `<div class="trend-day" title="${esc(d.date)}：${value == null ? '无记录' : `${value}${unit}`}"><span class="bar-value">${value == null ? '—' : Math.round(value)}</span><div class="bar-track"><i class="${key === 'accuracy' ? 'accuracy-bar' : ''}" style="height:${Math.max(0, Math.min(100, key === 'attempts' ? d.attempts / max * 100 : value || 0))}%"></i></div><span class="bar-date">${esc(d.date.slice(5))}</span></div>`; }).join('')}</div></figure>`;
    return `<section class="overview-card"><div class="summary-grid"><div class="summary-stat"><span class="muted">稳定掌握</span><strong>${stats.stable}<small> 词</small></strong></div><div class="summary-stat"><span class="muted">待复习</span><strong>${stats.review}<small> 词</small></strong></div><div class="summary-stat"><span class="muted">未学习</span><strong>${stats.unseen}<small> 词</small></strong></div><div class="summary-stat"><span class="muted">已经到期</span><strong>${stats.due}<small> 词</small></strong></div></div><p class="muted">稳定掌握：连续 3 次「认识且答对」，且尚未到期。旧版掌握标记仍保留：${stats.mastered} 词。累计作答 ${stats.attempts} 次，正确率 ${stats.attempts ? Math.round(stats.correct / stats.attempts * 100) : 0}%。</p><div class="result-actions"><button class="button primary" data-action="review-due">复习到期单词</button><button class="button secondary" data-action="review-all">复习待加强</button></div></section>
    <section class="analytics-section"><div class="overview-heading"><h2 class="section-heading">每个 List 的积累</h2><span class="muted">掌握率 = 已掌握词数 / 本组词数</span></div><div class="list-grid">${stats.lists.map(g => `<article class="list-card"><div><strong>List ${g.group}</strong><span>${Math.round(g.mastered / g.total * 100)}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${g.mastered / g.total * 100}%"></div></div><p>掌握 ${g.mastered}/${g.total} · 稳定 ${g.stable} · 未学 ${g.unseen}</p></article>`).join('')}</div></section>
    <section class="analytics-section"><h2 class="section-heading">最近 14 天</h2><p class="muted">每日作答次数含直接看答案；正确率按作答次数计算。趋势从升级后开始记录，旧版累计次数不会反推为历史曲线。</p><div class="trend-grid">${chart('attempts', '每日学习量 · 次', '次')}${chart('accuracy', '每日正确率 · %', '%')}</div><details class="data-table-details"><summary>查看每日详细数据</summary><div class="table-scroll"><table><thead><tr><th>日期</th><th>作答</th><th>不同单词</th><th>正确</th><th>正确率</th></tr></thead><tbody>${trend.map(d => `<tr><td>${esc(d.date)}</td><td>${d.attempts}</td><td>${d.unique}</td><td>${d.correct}</td><td>${d.accuracy == null ? '—' : `${Math.round(d.accuracy)}%`}</td></tr>`).join('')}</tbody></table></div></details></section>
    <section class="analytics-section"><h2 class="section-heading">最容易遗忘的词</h2><p class="muted">综合答错次数、错误率和最近表现排序；只显示已有作答记录的词。</p><div class="results-list">${stats.forgetful.slice(0, 15).map(r => { const w = words.find(w => String(w.id) === String(r.id)); return `<div class="result-row"><div><div class="result-word">${esc(w?.word || r.word)}</div><div class="result-meaning">${esc(w?.meaning)}</div><div class="muted">答错 ${r.lapseCount} 次 · 错误率 ${Math.round(r.errorRate * 100)}% · 复习 ${r.reviewCount} 次</div></div><button class="button secondary small" data-study-word="${esc(r.id)}">再记一次</button></div>`; }).join('') || '<div class="empty-state"><p>开始学习后，这里会列出需要多见几次的词。</p></div>'}</div></section>
    <section class="analytics-section settings-panel"><div><h2 class="section-heading">考前复习节奏</h2><p class="muted">普通节奏为 1 / 3 / 7 / 14 / 30 天；不认识或答错约 10 分钟后重现，模糊但答对约 30 分钟后重现。设置考试日期后压缩间隔。</p></div><form id="exam-date-form"><label class="field-label" for="exam-date">目标考试日期</label><div class="inline-form"><input type="date" id="exam-date" class="text-input" value="${esc(state.settings?.examDate || '')}"><button class="button primary" type="submit">保存节奏</button><button class="button secondary" type="button" data-action="clear-exam-date">恢复普通节奏</button></div></form><p class="muted">${state.settings?.examDate ? `当前目标：${esc(state.settings.examDate)}。已过的考试日期不会继续压缩周期。` : '当前使用普通复习节奏。'}到期优先，其次优先复习易忘词；测试模式仍随机抽题。</p></section>
    <section class="analytics-section settings-panel"><div><h2 class="section-heading">带走你的学习进度</h2><p class="muted">导出含作答记录、复习计划、每日趋势和未完成练习。导入先预览，再合并；重复导入不会重复累加作答次数。</p></div><div class="result-actions"><button class="button primary" data-action="export-progress">导出进度 JSON</button><button class="button secondary" data-action="import-progress">导入进度</button><input id="progress-file" type="file" accept=".json,application/json" hidden></div><p class="muted">当前练习会保留。单词计数取较大值，复习计划采用较新记录；不同设备的独立作答不会简单相加。导入前自动备份，存储失败时保留现状。</p></section>`;
  }
  function quality(index, words) {
    const flags = index.flags || [];
    const categories = [['释义疑点', ['meaning', 'english']], ['近义词疑点', ['synonyms']], ['例句、派生词与来源记录', ['example', 'derivatives', 'source']]];
    return `<section class="overview-card"><h2 class="section-heading">原文与校核，分开保存</h2><p>800 个词与 815 个考法的原始数据库保持不变。以下标记是排版、抽取或用法的待核验线索，不会静默替换词义。</p><p class="muted">部分近义词不在 800 词库内：仍显示在完整词条中，但不作为训练选项。关系只按原词表的具体考法使用，不扩大为双向、传递或绝对等价关系。</p><p class="muted">首版提取时的字体映射与标签整理也列入来源记录；原始 PDF 提取文本保留在项目 scripts 目录。</p></section>${categories.map(([title, fields]) => { const list = flags.filter(f => fields.includes(f.field)); return `<section class="analytics-section"><h2 class="section-heading">${title} <span class="muted">${list.length}</span></h2><div class="quality-list">${list.map(f => { const w = words.find(w => String(w.id) === String(f.wordId)); return `<article class="quality-item"><div><strong>${esc(w?.word || f.wordId)}</strong><span class="quality-badge">${fieldNames[f.field] || '待核验'}</span></div><p>${esc(f.message)}</p>${f.raw ? `<blockquote>${esc(f.raw)}</blockquote>` : ''}<p class="muted">PDF 第 ${esc(w?.page)} 页 · ${Number.isInteger(f.senseIndex) ? `考法 ${f.senseIndex + 1}` : '词条来源'} · 保留原文</p>${w ? `<button class="text-link" data-study-word="${esc(w.id)}">打开词卡 →</button>` : ''}</article>`; }).join('') || '<p class="muted">当前规则未发现此类疑点；这不代表所有内容已经人工核验。</p>'}</div></section>`; }).join('')}`;
  }
  function exam(active = 'TC') {
    const modules = { TC: { title: 'Text Completion · 句子填空', text: '预留句子、空格、选项、答案和来源说明的独立练习位置。' }, SE: { title: 'Sentence Equivalence · 句子等价', text: '预留句子、配对选项、答案依据和词义辨析的独立练习位置。' }, RC: { title: 'Reading Comprehension · 阅读理解', text: '预留文章、关联题目、证据定位和解析的独立练习位置。' } };
    const m = modules[active] || modules.TC;
    return `<div class="mode-tabs" role="group" aria-label="GRE 题型">${Object.keys(modules).map(k => `<button class="preset-button ${k === active ? 'active' : ''}" data-exam-module="${k}" aria-pressed="${k === active}">${k}</button>`).join('')}</div><section class="exam-placeholder"><span class="pill">模块已预留</span><h2>${m.title}</h2><p>${m.text}</p><p class="muted">当前题库为空，等待补充已核验并注明来源的材料。这里不会自动生成或冒充 GRE 真题。</p><button class="button primary" data-action="basic">先巩固词汇 →</button></section>`;
  }
  root.GREViews = { esc, date, wordDetails, analytics, quality, exam };
})(window);
